% This is an autogenerated sample test for file ExtractedPacking.m
classdef testExtractedPacking < matlab.unittest.TestCase

    methods (Test)

        function test_cutoffz_vertices_and_centers_methods_differ(testCase)
            % Three prisms stacked along z, all sharing radius=1 (so x/y
            % extents, and thus the target z-length used by cutoffz, are
            % fixed) and thickness=1:
            %   low  at z=0.0  (defines the packing's global zmin)
            %   mid  at z=0.6  (comfortably inside the post-cutoff range)
            %   high at z=1.2  (defines the packing's global zmax)
            %
            % cutoffz's post-cutoff z-range works out to [-0.333, 1.533]:
            %   - low's and high's *centers* (0 and 1.2) fall inside that
            %     range, so the "centers" method keeps all three prisms.
            %   - low's and high's *vertices* span [-0.5,0.5] and [0.7,1.7]
            %     respectively, each poking outside the range, so the
            %     "vertices" method keeps only mid.
            r = 1.0;
            t = 1.0;
            normal = [0,0,1];
            low  = HexagonalPrism([0,0,0.0], r, t, normal);
            mid  = HexagonalPrism([0,0,0.6], r, t, normal);
            high = HexagonalPrism([0,0,1.2], r, t, normal);

            ep = ExtractedPacking([low, mid, high]);

            epVertices = ep.cutoffz("Method", CutoffMethod.vertices);
            epCenters  = ep.cutoffz("Method", CutoffMethod.centers);

            testCase.verifyEqual(numel(epVertices.items), 1);
            testCase.verifyEqual(epVertices.items(1).position, mid.position);

            testCase.verifyEqual(numel(epCenters.items), 3);

            testCase.verifyNotEqual( ...
                numel(epVertices.items), numel(epCenters.items));
        end

        function test_cutoffz_default_method_matches_vertices(testCase)
            % Guards against the vertices/centers arms silently collapsing
            % back into each other: the no-Method-specified default must
            % keep behaving like CutoffMethod.vertices.
            r = 1.0;
            t = 1.0;
            normal = [0,0,1];
            low  = HexagonalPrism([0,0,0.0], r, t, normal);
            mid  = HexagonalPrism([0,0,0.6], r, t, normal);
            high = HexagonalPrism([0,0,1.2], r, t, normal);

            ep = ExtractedPacking([low, mid, high]);

            epDefault  = ep.cutoffz();
            epVertices = ep.cutoffz("Method", CutoffMethod.vertices);

            testCase.verifyEqual(numel(epDefault.items), numel(epVertices.items));
            testCase.verifyEqual(epDefault.items(1).position, epVertices.items(1).position);
        end

    end
end
